// Üretilen dosya: tool/ozgun/uret.py. Matematik ve Geometri · Üçgenlerde açı, kenar-açı bağıntıları, eşlik-benzerlik ve üçgenin yardımcı elemanları-merkezleri (ağırlık, iç-dış teğet, diklik, çevrel merkez) (zor).
const ozMathematics15Zor = <(String, String, List<String>, String)>[
  ('Bir kare ile bir eşkenar üçgen, karenin alt kenarı eşkenar üçgenin tabanı olacak biçimde karenin iç bölgesine doğru ortak kenarlı çiziliyor. Eşkenar üçgenin tepe noktasını karenin üst iki köşesine birleştiren doğru parçaları arasındaki geniş açı kaç derecedir?', '150°', ['120°', '135°', '165°'], 'Ortak kenardan dolayı yanlarda tepe açısı 90° - 60° = 30° olan iki eş ikizkenar üçgen oluşur. Taban açıları 75° olup üst köşelere giden parçalar arasındaki açı 360° - (60° + 75° + 75°) = 150° olur.'),
  ('ABCD karesinin [BC] kenarı üzerine, karenin dış bölgesinde kalacak şekilde BCE eşkenar üçgeni inşa ediliyor. A, E ve D noktalarının oluşturduğu AED açısının ölçüsü kaçtır?', '30°', ['15°', '25°', '45°'], '|AB| = |BC| = |BE| olduğundan ABE ikizkenar üçgendir ve m(ABE) = 150° iken m(AEB) = 15° olur. Simetriden m(DEC) = 15° olup m(AED) = 60° - (15° + 15°) = 30° bulunur.'),
  ('|AB| = |AC| olan ikizkenar bir ABC üçgeninin [BC] tabanı üzerinde alınan D noktası için |AD| = |BD| ve |AC| = |CD| eşitlikleri sağlanmaktadır. Bu üçgenin A köşesindeki tepe açısının tamamı kaç derecedir?', '108°', ['96°', '100°', '120°'], 'm(B) = x denirse |AD| = |BD| olduğundan m(BAD) = x ve dış açıdan m(ADC) = 2x olur. |AC| = |CD| ise m(CAD) = 2x ve m(C) = x bulunur. ACD üçgeninde 5x = 180° => x = 36° ve m(BAC) = 3x = 108° elde edilir.'),
  ('m(K) = 90° olan bir KLM dik üçgeninde dik köşeden hipotenüse indirilen yükseklik [KH] ve hipotenüse ait kenarortay [KD] olarak çiziliyor. m(HKD) = 22° ise bu üçgenin en küçük dar açısı kaç derecedir?', '34°', ['22°', '28°', '36°'], 'Dik üçgende dik köşeden çizilen yükseklik ile kenarortay arasındaki açı dar açıların farkına eşittir. m(L) + m(M) = 90° ve |m(L) - m(M)| = 22° sisteminden küçük dar açı (90° - 22°) / 2 = 34° bulunur.'),
  ('Bir ABC üçgeninde [BC] kenarı üzerindeki D noktasından [AB] kenarına indirilen dikme [AB] kenarını iki eş parçaya bölmektedir. |AC| = |AD| ve m(ACB) = 76° olduğuna göre m(BAC) açısının tamamı kaç derecedir?', '66°', ['58°', '64°', '72°'], '[AB]\'ye inen dikme kenarı ikiye böldüğünden |AD| = |BD| olur. |AC| = |AD| verildiğinden m(ADC) = m(ACB) = 76° ve m(DAC) = 180° - 152° = 28° bulunur. ABD üçgeninde 2·m(BAD) = 76° => m(BAD) = 38° olup m(BAC) = 38° + 28° = 66° elde edilir.'),
  ('Kesişen iki düzlem ayna arasındaki açı kaç derece olmalıdır ki birinci aynaya herhangi bir dar açıyla gelen ışık ışını her iki aynadan birer kez yansıdıktan sonra geliş doğrultusuna paralel ve zıt yönde geri dönsün?', '90 derece', ['45 derece', '60 derece', '120 derece'], 'Köşe yansıtıcı (retroreflektör) ilkesine göre iki ayna arasındaki açı θ = 90° olduğunda yansıma açıları tümler olur ve ışın geliş yönüne tam paralel geri yansır.'),
  ('m(BAC) = 90° olan bir ABC dik üçgeninde [BC] hipotenüsü üzerinde |BD| = |BA| ve |CE| = |CA| olacak şekilde D ve E noktaları işaretleniyor (B-E-D-C sıralamasıyla). Buna göre m(EAD) açısı kaç derecedir?', '45°', ['30°', '36°', '60°'], 'ABD ikizkenarında m(BDA) = 90° - B/2, ACE ikizkenarında m(AEC) = 90° - C/2 olur. AED üçgeninde m(EAD) = 180° - [(90° - B/2) + (90° - C/2)] = (B + C)/2 = 90°/2 = 45° sabittir.'),
  ('ABCD dikdörtgeni biçimindeki bir kağıtta D köşesi, [AC] köşegeni boyunca katlandığında D\' konumuna geliyor. m(ACD) = 28° olduğuna göre [CD\'] doğru parçasının [AB] kenarını kestiği K noktasında oluşan m(AKC) dar açısı kaç derecedir?', '56°', ['52°', '62°', '64°'], 'Paralellikten m(CAB) = m(ACD) = 28° ve katlama simetrisinden m(ACD\') = 28° olur. AKC üçgeninde C köşesindeki açı m(ACK) = 28° ve m(KAC) = 28° olduğundan dış açı m(CKB) = 56°, yani [CD\'] ile [AB] arasındaki dar açı 56° bulunur.'),
  ('m(B) = 68° ve m(C) = 46° olan bir ABC üçgeninin çevrel çember merkezi O noktasıdır. O noktasını B ve C köşelerine birleştiren yarıçapların oluşturduğu OBC ikizkenar üçgeninin taban açılarından biri kaç derecedir?', '24°', ['22°', '26°', '33°'], 'm(A) = 180° - (68° + 46°) = 66° bulunur. Çevrel çemberde aynı yayı gören merkez açı çevre açının iki katı olduğundan m(BOC) = 2 · 66° = 132° ve |OB| = |OC| ikizkenarlığından m(OBC) = (180° - 132°)/2 = 24° olur.'),
  ('Eşkenar bir ABC karton üçgeninde A köşesi, [AB] üzerindeki D ve [AC] üzerindeki E noktalarından geçen [DE] boyunca katlandığında [BC] kenarı üzerindeki A\' noktasına değiyor. m(BA\'D) = 50° olduğuna göre m(ADE) açısı kaç derecedir?', '55°', ['50°', '60°', '65°'], 'm(B) = 60° olduğundan BDA\' üçgeninde m(BDA\') = 180° - (60° + 50°) = 70° olur. Doğrusallık ve katlama simetrisinden 2·m(ADE) + 70° = 180° => m(ADE) = 55° bulunur.'),
  ('İkizkenar bir üçgende bir iç açının ölçüsü başka bir iç açının ölçüsünün tam 4 katına eşittir. Bu koşulu sağlayan farklı üçgenlerde tepe açısının alabileceği değerlerin toplamı kaç derecedir?', '140°', ['120°', '135°', '150°'], 'İlk durumda tabanlar x ve tepe 4x alınırsa 6x = 180° => tepe açısı 120° olur. İkinci durumda tepe x ve tabanlar 4x alınırsa 9x = 180° => tepe açısı 20° olur; toplamları 120° + 20° = 140° bulunur.'),
  ('Tüm iç açıları 90 dereceden küçük olan (dar açılı) bir KLM üçgeninde |KL| = 8 birim ve |KM| = 10 birimdir. |LM| kenarının birim cinsinden alabileceği kaç farklı tam sayı değeri vardır?', '6 adet', ['7 adet', '8 adet', '9 adet'], 'Üç açının da dar olması için hem x² < 8² + 10² = 164 hem de 10² < 8² + x² yani x² > 36 sağlanmalıdır. 6 < x < √164 (yaklaşık 12,8) aralığındaki tam sayılar 7, 8, 9, 10, 11 ve 12 olup 6 adettir.'),
  ('|AB| = 10 birim ve |AC| = 16 birim olan bir ABC üçgeninde A köşesinden [BC] kenarına çizilen kenarortayın uzunluğu (Va) en fazla kaç birim tam sayı değer alabilir?', '12 birim', ['11 birim', '13 birim', '15 birim'], 'Kenarortay eşitsizliğine göre |16 - 10|/2 < Va < (16 + 10)/2 yani 3 < Va < 13 bağıntısı geçerlidir; bu nedenle Va en çok 12 birim tam sayı değerini alır.'),
  ('Çevresi 40 birim olan bir üçgenin üç kenarortayının uzunlukları toplamının alabileceği en küçük tam sayı değeri kaç birimdir?', '31 birim', ['21 birim', '29 birim', '30 birim'], 'Bir üçgende kenarortaylar toplamı T, çevrenin 3/4\'ü ile çevrenin kendisi arasındadır: (3/4)·40 < T < 40 => 30 < T < 40 olduğundan en küçük tam sayı 31 birimdir.'),
  ('ABC üçgeninde |AB| = (2x - 1) cm, |AC| = (x + 4) cm ve |BC| = 11 cm olarak veriliyor. m(ABC) > m(ACB) olduğu bilindiğine göre x\'in alabileceği tam sayı değerlerinin toplamı kaçtır?', '7', ['6', '9', '12'], 'm(B) > m(C) olduğundan |AC| > |AB| => x + 4 > 2x - 1 => x < 5 bulunur. Üçgen eşitsizliğinden (2x - 1) + (x + 4) > 11 => 3x > 8 => x > 8/3 elde edilir; (8/3, 5) aralığındaki tam sayılar 3 ve 4 olup toplamları 7\'dir.'),
  ('Bir çeşitkenar veya ikizkenar üçgende iki kenara ait yükseklikler ha = 4 cm ve hb = 6 cm olarak ölçülüyor. Üçüncü kenara ait yükseklik hc\'nin santimetre cinsinden alabileceği en büyük tam sayı değeri kaçtır?', '11 cm', ['9 cm', '10 cm', '12 cm'], 'Kenarlar 2S/ha, 2S/hb, 2S/hc yazılıp üçgen eşitsizliğine konulduğunda |1/4 - 1/6| < 1/hc < 1/4 + 1/6 yani 1/12 < 1/hc < 5/12 elde edilir. Buradan 2,4 < hc < 12 çıkar ve en büyük tam sayı 11 cm olur.'),
  ('İki kenar uzunluğu 5 cm ve 8 cm olan, kenarları tam sayı olmak zorunda olmayan bir ABC üçgeninde 8 cm\'lik ve 5 cm\'lik kenarların arasındaki açı geniş açıdır. Bu üçgenin çevresinin alabileceği tam sayı değerleri kaç tanedir?', '3 tam sayı', ['2 tam sayı', '4 tam sayı', '5 tam sayı'], 'Geniş açı karşısındaki kenar x için √(5² + 8²) < x < 5 + 8 yani √89 (yaklaşık 9,43) < x < 13 olur. Çevre = 13 + x için 22,43 < Çevre < 26 aralığındaki tam sayılar 23, 24 ve 25 olup 3 tanedir.'),
  ('Bir ABC üçgeninin iç bölgesindeki K noktasından üç kenara indirilen dikme ayakları sırasıyla [AB] üzerinde F, [BC] üzerinde D ve [AC] üzerinde E noktalarıdır. |AF| = 3 cm, |BD| = 5 cm, |CE| = 6 cm, |FB| = 4 cm ve |DC| = 3 cm ise |AE| uzunluğu kaç santimetredir?', '3√5 cm', ['6 cm', '√41 cm', '7 cm'], 'Carnot diklik bağıntısına göre kenarlar üzerindeki atlamalı parçaların kareleri toplamı birbirine eşittir: |AF|² + |BD|² + |CE|² = |FB|² + |DC|² + |AE|² => 9 + 25 + 36 = 16 + 9 + |AE|² => |AE|² = 45 ve |AE| = 3√5 cm bulunur.'),
  ('m(ABC) = 90° olan bir dik üçgende hipotenüse [BD] dikmesi, D noktasından da [BC] dik kenarına [DE] dikmesi indiriliyor. |AD| = 2 cm ve |DC| = 6 cm olduğuna göre |BE| uzunluğu kaç santimetredir?', '√3 cm', ['2√3 cm', '3√3/2 cm', '2 cm'], 'ABC dik üçgeninde Öklid bağıntılarıyla |BC|² = 6 · (2 + 6) = 48 => |BC| = 4√3 cm ve |BD|² = 2 · 6 = 12 bulunur. BDC dik üçgeninde yine Öklid bağıntısından |BD|² = |BE| · |BC| => 12 = |BE| · 4√3 => |BE| = √3 cm elde edilir.'),
  ('m(BAC) = 90° olan bir ABC dik üçgeninde [AH] ⊥ [BC] ve H noktasından [AC] dik kenarına [HK] ⊥ [AC] dikmesi çiziliyor. |AK| = 9 cm ve |KC| = 16 cm olduğuna göre |BH| uzunluğu kaç santimetredir?', '45/4 cm', ['9 cm', '12 cm', '25/2 cm'], 'm(AHC) = 90° olan dik üçgende hipotenüs |AC| = 25 cm olup Öklid bağıntısından |AH|² = 9 · 25 = 225 => |AH| = 15 cm ve |HC|² = 16 · 25 = 400 => |HC| = 20 cm bulunur. ABC dik üçgeninde |AH|² = |BH| · |HC| => 225 = |BH| · 20 => |BH| = 45/4 cm olur.'),
  ('Dar açıları 22,5° ve 67,5° olan bir dik üçgenin 22,5 derecelik açısının karşısındaki kısa dik kenarı 4 birim ise 67,5 derecelik açının karşısındaki uzun dik kenarı kaç birimdir?', '4 + 4√2 birim', ['8 birim', '4√2 birim', '8 + 4√2 birim'], '67,5 derecelik açıdan 22,5° ayıracak biçimde doğru parçası çizildiğinde ikizkenar üçgen ve 45°-45°-90° dik üçgeni oluşur; kısa kenar a = 4 iken uzun dik kenar a(1 + √2) = 4 + 4√2 birim olur.'),
  ('Dışbükey bir ABCD dörtgeninde m(A) = 60°, m(B) = 90°, m(D) = 90°, |BC| = 2√3 cm ve |CD| = 4√3 cm olarak veriliyor. Buna göre |AB| kenarının uzunluğu kaç santimetredir?', '10 cm', ['8 cm', '9 cm', '12 cm'], '[AD] ve [BC] doğruları uzatılarak E noktasında kesiştirildiğinde m(E) = 30° olan büyük bir 30°-60°-90° üçgeni oluşur. Küçük CDE dik üçgeninde 30° karşısı |CD| = 4√3 cm ise hipotenüs |CE| = 8√3 cm olur. |BE| = 2√3 + 8√3 = 10√3 cm olduğundan 60° karşısı 10√3 cm ise 30° karşısı |AB| = 10 cm bulunur.'),
  ('Eşkenar bir ABC üçgeninin dış bölgesinde ve [BC] kenarı tarafında alınan P noktasından [AB] ve [AC] doğrularına indirilen dikmeler sırasıyla 7√3 birim ve 4√3 birim, [BC] kenarına indirilen dikme ise 2√3 birimdir. ABC üçgeninin bir kenarı kaç birimdir?', '18 birim', ['16 birim', '20 birim', '22 birim'], 'Bir kenarın dış tarafındaki noktadan yan kenar doğrularına inen dikmeler toplamından yakın kenara inen dikme çıkarıldığında eşkenar üçgenin yüksekliği elde edilir: h = 7√3 + 4√3 - 2√3 = 9√3 birim. Buradan a√3 / 2 = 9√3 => a = 18 birimdir.'),
  ('m(A) = 90° olan ABC dik üçgeni biçimindeki kağıtta |AB| = 6 cm ve |AC| = 8 cm\'dir. [AB] dik kenarı, [BD] katlama izi boyunca katlandığında [BC] hipotenüsü üzerindeki [A\'B] doğru parçasıyla tam çakıştığına göre |AD| kaç santimetredir?', '3 cm', ['8/3 cm', '10/3 cm', '4 cm'], 'Hipotenüs |BC| = 10 cm olup katlama sonucunda |BA\'| = |BA| = 6 cm, |A\'C| = 10 - 6 = 4 cm ve m(BA\'D) = 90° olur. |AD| = |A\'D| = x denirse |DC| = 8 - x olur; DA\'C dik üçgeninde x² + 4² = (8 - x)² => 16x = 48 => x = 3 cm bulunur.'),
  ('m(A) = 90°, |AB| = 9 cm ve |AC| = 12 cm olan ABC dik üçgen biçimindeki kartonda [AC] dik kenarı, [CD] katlama çizgisi boyunca katlandığında [BC] hipotenüsü üzerindeki [A\'C] konumuna tam oturuyor. Buna göre |AD| uzunluğu kaç santimetredir?', '4 cm', ['3 cm', '4,5 cm', '5 cm'], 'Hipotenüs |BC| = 15 cm olup katlama sonucunda |A\'C| = |AC| = 12 cm, |BA\'| = 15 - 12 = 3 cm ve m(CA\'D) = 90° olur. |AD| = |A\'D| = x denirse |BD| = 9 - x bulunur; BDA\' dik üçgeninde x² + 3² = (9 - x)² => 18x = 72 => x = 4 cm elde edilir.'),
  ('m(B) = 90° olan bir ABC dik üçgeninde [AB] dik kenarı üzerinde M, [BC] dik kenarı üzerinde N noktası alınıyor. |AN| = 11 cm, |CM| = 8 cm ve |MN| = 5 cm olduğuna göre |AC| hipotenüsünün uzunluğu kaç santimetredir?', '4√10 cm', ['12 cm', '13 cm', '6√5 cm'], 'Dik kenarlar üzerinde alınan M ve N noktaları için dört ayrı Pisagor bağıntısı toplanırsa |AN|² + |CM|² = |AC|² + |MN|² özdeşliği elde edilir. 11² + 8² = |AC|² + 5² => 121 + 64 - 25 = 160 => |AC| = √160 = 4√10 cm bulunur.'),
  ('Aralarında 9 metre yatay mesafe bulunan yere dik iki direkten birinin boyu 7 metre, diğerinin boyu 5 metredir. Birinci direğin tepesinden çıkıp yerdeki bir yem tanesini aldıktan sonra ikinci direğin tepesine konan bir kuşun alabileceği en kısa yol kaç metredir?', '15 metre', ['13 metre', '14 metre', '16 metre'], 'Kısa direğin zemin doğrusuna göre simetriği alındığında dikey toplam mesafe 7 + 5 = 12 metre, yatay mesafe 9 metre olur. En kısa doğrusal yol √(9² + 12²) = 15 metredir.'),
  ('Kenar uzunlukları √13 birim, √17 birim ve √20 birim olan bir üçgende √20 birimlik kenara ait yüksekliğin uzunluğu kaç birimdir?', '7/√5 birim', ['3 birim', '6/√5 birim', '8/√5 birim'], '√20 = 2√5 kenarına inen dikme kenarı x ve 2√5 - x diye bölerse 13 - x² = 17 - (20 - 4√5x + x²) => 4√5x = 16 => x = 4/√5 olur. Yükseklik h = √(13 - 16/5) = √(49/5) = 7/√5 birim bulunur.'),
  ('ABCD dörtgeninde [AB] ⊥ [BC], [AD] ⊥ [DC], m(BAD) = 120°, |AB| = 4 cm ve |AD| = 6 cm olarak veriliyor. Buna göre |DC| kenarının uzunluğu kaç santimetredir?', '14/√3 cm', ['4√3 cm', '16/√3 cm', '5√3 cm'], '[BA ve [CD doğruları uzatılarak K noktasında kesiştirildiğinde m(KAB) = 60° ve m(K) = 30° olur. ABK (30°-60°-90°) üçgeninde 30° karşısı |AB| = 4 cm olduğundan hipotenüs |AK| = 8 cm bulunur. KDC dik üçgeninde 60° karşısı |KD| = 8 + 6 = 14 cm olduğundan 30° karşısı |DC| = 14/√3 cm elde edilir.'),
  ('Kenar uzunlukları tam sayı olan bir dik üçgenin dik kenarlarından biri 11 birim asal sayısına eşittir. Bu dik üçgenin hipotenüs uzunluğu kaç birimdir?', '61 birim', ['59 birim', '60 birim', '65 birim'], 'c² - b² = 11² = 121 => (c - b)(c + b) = 1 · 121 çarpanlarından c - b = 1 ve c + b = 121 bulunur. Taraf tarafa toplandığında 2c = 122 ve hipotenüs c = 61 birim elde edilir.'),
  ('Dik kenarları 7 cm ve 24 cm olan bir dik üçgenin hipotenüse ait yüksekliği h ve hipotenüse ait kenarortayı V olduğuna göre V - h farkı kaç santimetredir?', '289/50 cm', ['261/50 cm', '6 cm', '301/50 cm'], '7-24-25 dik üçgeninde muhteşem üçlüden V = 25/2 = 625/50 cm ve Öklid\'den h = (7 · 24) / 25 = 168/25 = 336/50 cm olur. Farkları 625/50 - 336/50 = 289/50 cm bulunur.'),
  ('m(B) = 90° olan ikizkenar ABC dik üçgeninin iç bölgesinde alınan P noktası için |PA| = 3 cm, |PB| = 2 cm ve m(APB) = 135° olarak veriliyor. Buna göre |PC| uzunluğu kaç santimetredir?', '√17 cm', ['4 cm', '2√5 cm', '5 cm'], 'ABP üçgeni B köşesi etrafında [AB] kenarı [BC] üzerine oturacak şekilde 90° döndürüldüğünde P noktası P\' konumuna gelir; |BP\'| = 2 cm ve m(PBP\') = 90° olduğundan |PP\'| = 2√2 cm ve m(PP\'B) = 45° olur. m(CP\'B) = 135° olduğundan m(PP\'C) = 135° - 45° = 90° bulunur ve PP\'C dik üçgeninde |PC| = √((2√2)² + 3²) = √17 cm elde edilir.'),
  ('m(A) = 90° olan ABC dik üçgeninde [AB] kenarının orta noktası K, [AC] kenarının orta noktası L\'dir. |BL| = 7 birim ve |CK| = 4√6 birim olduğuna göre |BC| hipotenüsü kaç birimdir?', '√116 birim', ['10 birim', '√108 birim', '11 birim'], '|AK| = |KB| = c ve |AL| = |LC| = b denirse ABL dik üçgeninde 4c² + b² = 49, ACK dik üçgeninde c² + 4b² = 96 olur. Taraf tarafa toplandığında 5(b² + c²) = 145 => b² + c² = 29 bulunur. Hipotenüs |BC| = √(4b² + 4c²) = 2√29 = √116 birimdir.'),
  ('Bir üçgende m(B) = 30°, m(C) = 15° ve |AC| = 8 cm olarak veriliyor. Buna göre en uzun kenar olan |BC| kaç santimetredir?', '8√2 cm', ['8√3 cm', '12 cm', '16 cm'], 'm(BAC) = 135° olup [BA kenarı A yönünde uzatılıp C\'den [CH] dikmesi indirildiğinde m(CAH) = 45° olur; |AC| = 8 cm olduğundan |CH| = 4√2 cm bulunur. CHB dik üçgeninde 30° karşısı |CH| = 4√2 cm ise hipotenüs |BC| = 8√2 cm elde edilir.'),
  ('Dışbükey bir ABCD dörtgeninde [AD] kenarının orta noktası E, [BC] kenarının orta noktası F ve [BD] köşegeninin orta noktası K olarak işaretleniyor. |AB| = 10 cm, |DC| = 24 cm ve [AB] ⊥ [DC] olduğuna göre |EF| uzunluğu kaç santimetredir?', '13 cm', ['12 cm', '15 cm', '17 cm'], 'ABD üçgeninde [EK] orta taban olduğundan |EK| = 5 cm ve [EK] // [AB]; BCD üçgeninde [KF] orta taban olduğundan |KF| = 12 cm ve [KF] // [DC] olur. [AB] ⊥ [DC] verildiğinden m(EKF) = 90° ve |EF| = √(5² + 12²) = 13 cm bulunur.'),
  ('Kenar uzunlukları 4 birim, 6 birim ve 9 birim olan bir üçgene benzer olan ve iki kenarının uzunluğu 6 birim ile 9 birim olarak bilinen, ilk üçgene eş olmayan başka bir üçgenin üçüncü kenarı kaç birimdir?', '13,5 birim', ['12 birim', '13 birim', '15 birim'], 'Üçgenler eş olmadığından üçüncü kenar 4 birim olamaz. Dolayısıyla 6 ve 9 birimlik kenarlar küçük üçgenin 4 ve 6 birimlik kenarlarıyla eşleşir: 6/4 = 9/6 = x/9 = 3/2 orantısından x = 13,5 birim bulunur.'),
  ('Kenar uzunlukları |AB| = 8 cm ve |BC| = 10 cm olan ABCD dikdörtgeni biçimindeki kağıtta D köşesi, [BC] kenarı üzerindeki K noktasına gelecek biçimde [AF] (F ∈ [CD]) boyunca katlanıyor. Buna göre |CF| uzunluğu kaç santimetredir?', '3 cm', ['2,5 cm', '4 cm', '5 cm'], 'Katlama sonucunda |AK| = |AD| = 10 cm ve m(AKF) = 90° olur. ABK dik üçgeninde |BK| = √(10² - 8²) = 6 cm ve |KC| = 10 - 6 = 4 cm bulunur. ABK ~ KCF benzerliğinden 8 / 4 = 6 / |CF| => |CF| = 3 cm elde edilir.'),
  ('Bir kenar uzunluğu 9 cm olan ABC eşkenar üçgeninin [BC] kenarı üzerinde |BD| = 3 cm olacak şekilde D noktası işaretleniyor. [AB] üzerinde K ve [AC] üzerinde L noktaları m(KDL) = 60° ve |BK| = 4 cm koşulunu sağladığına göre |CL| uzunluğu kaç santimetredir?', '4,5 cm', ['3,5 cm', '4 cm', '5 cm'], '|DC| = 9 - 3 = 6 cm\'dir. m(B) = m(C) = 60° ve m(KDL) = 60° olduğundan m(BKD) = m(CDL) olur ve BKD ~ CDL benzerliği elde edilir: |BK| / |CD| = |BD| / |CL| => 4 / 6 = 3 / |CL| => |CL| = 4,5 cm bulunur.'),
  ('Menelaus teoreminin uygulandığı bir ABC üçgeninde [BC] kenarının C yönündeki uzantısı üzerinde |BC| = 2|CD| olacak biçimde D noktası, [AB] kenarı üzerinde |AF| = 3|FB| olacak biçimde F noktası alınıyor. D ve F\'den geçen doğru [AC] kenarını E noktasında kestiğine göre |AE| / |EC| oranı kaçtır?', '9', ['6', '8', '12'], 'Menelaus bağıntısına göre (|DB| / |DC|) · (|CE| / |EA|) · (|AF| / |FB|) = 1 yazılır. |DB|/|DC| = 3/1 ve |AF|/|FB| = 3/1 olduğundan 3 · (|CE|/|EA|) · 3 = 1 => |AE| / |EC| = 9 bulunur.'),
  ('Köşelerden karşı kenarlara çizilen [AD], [BE] ve [CF] doğru parçaları ABC üçgeninin iç bölgesindeki P noktasında kesişmektedir. |BD| / |DC| = 2/5 ve |CE| / |EA| = 15/4 olduğuna göre |AF| / |FB| oranı kaçtır?', '2/3', ['3/2', '3/4', '4/3'], 'Ceva teoremine göre (|BD| / |DC|) · (|CE| / |EA|) · (|AF| / |FB|) = 1 eşitliği sağlanır: (2/5) · (15/4) · (|AF| / |FB|) = 1 => (3/2) · (|AF| / |FB|) = 1 => |AF| / |FB| = 2/3 elde edilir.'),
  ('m(B) = 90° olan ABC dik üçgeninde [AC] hipotenüsünün orta noktası M\'den hipotenüse çizilen dikme [BC] dik kenarını K noktasında kesmektedir. |AB| = 9 cm ve |BC| = 12 cm olduğuna göre |KC| uzunluğu kaç santimetredir?', '75/8 cm', ['8 cm', '9 cm', '85/8 cm'], '9-12-15 dik üçgeninde |AC| = 15 cm ve |MC| = 7,5 cm olur. m(C) açısı ortak olduğundan MKC ~ ABC dik üçgen benzerliği kurulur: |MC| / |BC| = |KC| / |AC| => 7,5 / 12 = |KC| / 15 => |KC| = 112,5 / 12 = 75/8 cm bulunur.'),
  ('Köşeleri A, B ve C olan bir üçgende D ∈ [AB] ve A-F-E-C noktaları [AC] kenarı üzerinde doğrusal olacak biçimde [DF] // [BE] ve [DE] // [BC] paralellikleri çiziliyor. |AF| = 4 cm ve |FE| = 6 cm olduğuna göre |EC| uzunluğu kaç santimetredir?', '15 cm', ['9 cm', '12 cm', '18 cm'], '[DF] // [BE] olduğundan |AD| / |AB| = |AF| / |AE| = 4 / 10; [DE] // [BC] olduğundan |AD| / |AB| = |AE| / |AC| = 10 / (10 + |EC|) olur. İki oran eşitlendiğinde 4 / 10 = 10 / (10 + |EC|) => |EC| = 15 cm bulunur.'),
  ('Bir ABC üçgeninde [AC] kenarının orta noktası E ve [BC] kenarı üzerinde |BD| = 2|DC| koşulunu sağlayan D noktası veriliyor. [AD] ile [BE] doğru parçaları K noktasında kesiştiğine göre |AK| / |KD| oranı kaçtır?', '3/2', ['2', '4/3', '5/2'], 'E noktasından [AD]\'ye paralel [EF] (F ∈ [BC]) çizildiğinde orta tabandan |DF| = |FC| olur. |DC| = 2m alınırsa |DF| = m, |FC| = m ve |BD| = 4m bulunur. BFE\'de |KD| / |EF| = 4 / 5 => |EF| = 5|KD|/4; ADC\'de orta tabandan |AD| = 2|EF| = 5|KD|/2 olup |AK| = 5|KD|/2 - |KD| = 3|KD|/2 ve oran 3/2 olur.'),
  ('Yükseklik ayakları E ∈ [AC] ve F ∈ [AB] olan dar açılı bir ABC üçgeninde [EF] doğru parçası çiziliyor. m(A) = 60° ve |BC| = 16 cm olduğuna göre |EF| uzunluğu kaç santimetredir?', '8 cm', ['4√3 cm', '8√3 cm', '12 cm'], 'AEB ~ AFC benzerliğinden |AE| / |AB| = |AF| / |AC| = cos 60° = 1/2 yazılır. A açısı da ortak olduğundan KAK benzerliğiyle AEF ~ ABC (antiparalel kesen) olur ve benzerlik oranı cos 60° = 1/2 olduğundan |EF| = 16 · (1/2) = 8 cm bulunur.'),
  ('m(ACB) = 90° olan ABC dik üçgeninin dış bölgesine, hipotenüs [AB] kenarı üzerine A-B-D-E köşe sırasıyla ABDE karesi çiziliyor. E köşesinden [AC] doğrusunun A yönündeki uzantısına indirilen dikme ayağı H olup |AC| = 7 cm ve |BC| = 17 cm olduğuna göre |CH| uzunluğu kaç santimetredir?', '24 cm', ['20 cm', '23 cm', '25 cm'], 'm(EAH) + m(BAC) = 90° ve |AE| = |AB| olduğundan EHA ≅ ACB dik üçgen eşliği oluşur. Buradan |AH| = |BC| = 17 cm bulunur ve C, A, H doğrusal olduğundan |CH| = 7 + 17 = 24 cm elde edilir.'),
  ('Bir sokak arasında karşılıklı iki dik apartmanın arasına gerilen çamaşır ipinin tam ortasına asılan ağırlık nedeniyle ip V biçiminde simetrik esnemektedir; ancak sol bina bağlantısı yerden 9 m, sağ bina bağlantısı yerden 9 m yüksekte ve binalar arası 12 m iken ipin en alt noktası yerden 4 m yüksektedir. Sol binadan yatayda 2 m uzaklıktaki ip noktasının yerden yüksekliği kaç metredir?', '22/3 metre', ['7 metre', '23/3 metre', '8 metre'], 'Simetriden V\'nin en alt köşesi yatayda 6 m ortadadır ve bağlantı hizasından 9 - 4 = 5 m aşağıdadır. Sol bağlantıdan yatayda 2 m ileride ipin alçalma miktarı d için benzerlikten d / 5 = 2 / 6 => d = 5/3 m olur; yerden yükseklik 9 - 5/3 = 22/3 metredir.'),
  ('Çeşitkenar ABC üçgeninde [BC] kenarı üzerinde |BD| = 4 cm ve |DC| = 5 cm olacak biçimde D noktası, [AD] doğru parçası üzerinde ise |AE| = 2|ED| olacak biçimde E noktası alınıyor. [BE ışını [AC] kenarını F noktasında kestiğine göre |AF| / |FC| oranı kaçtır?', '8/9', ['2/9', '4/9', '2/5'], 'D noktasından [BF]\'ye paralel [DK] (K ∈ [AC]) çizildiğinde |FC| / |KC| = |BC| / |DC| = 9 / 5, yani |KC| = 5t ve |FK| = 4t olur. ADC üçgeninde [EF] // [DK] olduğundan |AF| / |FK| = |AE| / |ED| = 2 / 1 => |AF| = 8t bulunur; buradan |AF| / |FC| = 8/9 elde edilir.'),
  ('Eş iki dik üçgen biçimindeki flamanın dik kenarları 9 cm ve 12 cm\'dir. Bu iki flama hipotenüsleri tam çakışacak ancak dik köşeleri hipotenüsün zıt taraflarında kalacak ve bir dikdörtgen oluşturmayacak biçimde (deltoid olarak) birleştiriliyor. İki dik köşe arasındaki doğrusal uzaklık kaç santimetredir?', '14,4 cm', ['12 cm', '13,6 cm', '15 cm'], 'Deltoid simetrisinde hipotenüs (15 cm) dik köşeleri birleştiren doğru parçasını dik ve iki eş parçaya böler. Bir dik köşenin hipotenüse uzaklığı h = (9 · 12) / 15 = 7,2 cm olduğundan iki dik köşe arası 2 · 7,2 = 14,4 cm olur.'),
  ('İç içe çizilmiş iki eşkenar üçgenden dıştakinin bir kenarı 20 cm, içtekinin her köşesi dıştaki üçgenin birer kenarını 1:3 oranında (5 cm ve 15 cm olarak) aynı dönme yönünde bölmektedir. İçte oluşan üçgenin bir kenar uzunluğu kaç santimetredir?', '5√7 cm', ['10√2 cm', '12 cm', '10√3 cm'], 'Köşelerde oluşan üç küçük üçgen KAK eşliğine göre birbirine eştir (kenarları 5 cm ve 15 cm, aradaki açı 60°). İçteki eşkenar üçgenin kenarı 60° karşısında olup dikme indirildiğinde √((5√3/2)² + (15 - 5/2)²) = √(75/4 + 625/4) = √(700/4) = 5√7 cm bulunur.'),
  ('ABCD paralelkenarında [AD] kenarının orta noktası E, [AB] kenarının orta noktası F\'dir. [DB] köşegeni [CE] ve [CF] doğru parçalarını sırasıyla K ve L noktalarında kestiğine göre |KL| / |BD| oranı kaçtır?', '1/3', ['1/4', '2/5', '1/2'], 'Kelebek benzerliğinden |DK| / |KB| = |DE| / |BC| = 1 / 2 => |DK| = |BD|/3 ve simetrik olarak |BL| / |LD| = |BF| / |DC| = 1 / 2 => |BL| = |BD|/3 bulunur. Geriye kalan orta parça |KL| = |BD| - 2(|BD|/3) = |BD|/3 olduğundan oran 1/3\'tür.'),
  ('m(A) = 90° olan ABC dik üçgeninde [AD] ⊥ [BC] yüksekliği çiziliyor. |AB| = 15 cm ve |AC| = 20 cm olduğuna göre ABD üçgeninin iç teğet çember yarıçapının ADC üçgeninin iç teğet çember yarıçapına oranı kaçtır?', '3/4', ['9/16', '4/5', '3/5'], 'Hipotenüse inen dikme ile oluşan ABD ve CAD dik üçgenleri birbirine benzerdir ve hipotenüsleri |AB| = 15 cm ile |AC| = 20 cm\'dir. Benzer üçgenlerde iç teğet yarıçapları oranı benzerlik oranına eşittir: 15 / 20 = 3 / 4.'),
  ('ABC üçgeninde [AD] ve [BE] kenarortayları G noktasında kesişmektedir. [DE] orta tabanı ile [AB] kenarı arasında kalan kestiği [GD] ve [GE] parçaları için A ve B\'den [DE]\'ye birleştirilen doğru parçalarının kesimi F ise |GF| / |AF| oranı kaçtır?', '1/3', ['1/4 oranı', '1/2 oranı', '2/5 oranı'], '[AF] doğru parçası [AD] kenarortayı üzerindedir ve F noktası [DE] orta tabanının orta noktası olduğundan 3-1-2 kuralı gereği |AF| = 3k, |FG| = k, |GD| = 2k dizilimi oluşur; |GF| / |AF| = 1/3 olur.'),
  ('ABC üçgeninde A köşesindeki dış açıortay BC uzantısını C tarafında D noktasında kesiyor. |AB| = 9 cm, |AC| = 6 cm ve |BC| = 5 cm olduğuna göre |AD| dış açıortay parçasının uzunluğu kaç santimetredir?', '4√6 cm', ['6√2 santimetre', '6√3 santimetre', '10 santimetre'], 'Dış açıortay oranından |CD| / (|CD| + 5) = 6 / 9 = 2 / 3 => |CD| = 10 cm ve |BD| = 15 cm bulunur. Uzunluk formülünden |AD|² = |CD| · |BD| - |AC| · |AB| = 10 · 15 - 6 · 9 = 150 - 54 = 96 => |AD| = 4√6 cm elde edilir.'),
  ('ABC dik üçgeninde m(A) = 90° ve iç teğet çember [BC] hipotenüsüne D noktasında teğet olup |BD| = 4 cm ve |DC| = 6 cm ayırmaktadır. Buna göre ABC dik üçgeninin alanı kaç santimetrekaredir?', '24 cm²', ['20 santimetrekare', '30 santimetrekare', '48 santimetrekare'], 'İç teğet yarıçapı r alınırsa dik kenarlar 4 + r ve 6 + r, hipotenüs 10 cm olur: (4+r)² + (6+r)² = 100 => 2r² + 20r + 52 = 100 => r² + 10r = 24 (r = 2 cm, 6-8-10 üçgeni). Alan = (4+r)(6+r)/2 = (24 + 10r + r²)/2 = 48/2 = 4 · 6 = 24 cm² bulunur.'),
  ('ABC üçgeninde [AC] kenarı uzatılarak C tarafında |AC| = |CD| olacak biçimde D noktası, [BC] kenarı uzatılarak B tarafında |CB| = 2 · |BE| olacak biçimde E noktası alınıyor. Alan(ABC) = 16 cm² olduğuna göre Alan(ECD) kaç santimetrekaredir?', '24 cm²', ['16 santimetrekare', '32 santimetrekare', '48 santimetrekare'], 'C köşesindeki açılar ters değil bütünlerdir; sin(ECD) = sin(180° - ACB) = sin(ACB) olur! |CD| = |AC| = b ve |CE| = |CB| + |BE| = a + a/2 = (3/2)a olduğundan sinüs alan oranıyla Alan(ECD) = (1/2) · b · (3a/2) · sin(C) = (3/2) · Alan(ABC) = (3/2) · 16 = 24 cm² bulunur.'),
  ('İkizkenar bir üçgenin eş yan kenarları 10\'ar cm, tabanı 12 cm\'dir. Bu üçgenin çevrel çemberinin yarıçapı kaç santimetredir?', '25/4 cm', ['5 santimetre', '6 santimetre', '15/2 santimetre'], 'Tabana inen yükseklik √(10² - 6²) = 8 cm ve Alan = (12 · 8) / 2 = 48 cm²\'dir. Alan = abc / (4R) bağıntısından 48 = (10 · 10 · 12) / (4R) => 48 = 300 / R => R = 300 / 48 = 25/4 cm bulunur.'),
  ('ABC dik üçgen biçimindeki bir kağıtta m(B) = 90°, |AB| = 6 cm ve |BC| = 8 cm\'dir. Kağıt, A köşesi C köşesinin üzerine gelecek biçimde katlanıp açıldığında oluşan kat izinin uzunluğu kaç santimetredir?', '15/4 cm', ['7/2 santimetre', '4 santimetre', '9/2 santimetre'], 'A köşesini C\'ye çakıştıran kat izi [AC] hipotenüsünün orta dikmesidir. |AC| = 10 cm olduğundan yarısı 5 cm\'dir ve kat izi [BC] kenarını keser. Oluşan dik üçgen CBA dik üçgenine benzerdir: x / 5 = 6 / 8 => x = 30 / 8 = 15/4 cm bulunur.'),
  ('Dik kenarları |AB| = 6 cm ve |BC| = 8 cm olan ABC dik üçgeni biçimindeki bir karton, [AC] hipotenüsü üzerindeki bir noktadan [BC] kenarına paralel kesilerek bir dik yamuk ve küçük bir dik üçgen elde ediliyor. İki parçanın çevreleri eşit olduğuna göre küçük dik üçgenin kısa dik kenarı kaç santimetredir?', '9/2 cm', ['3 santimetre', '15/4 santimetre', '5 santimetre'], 'Benzerlikten küçük dik üçgenin kenarları 3k, 4k ve 5k alınırsa (büyük üçgen k=2 için 6, 8, 10) küçük üçgenin çevresi 12k olur. Yamuğun çevresi (6 - 3k) + 8 + (10 - 5k) + 4k = 24 - 4k\'dır. 12k = 24 - 4k => 16k = 24 => k = 3/2 ve kısa dik kenar 3k = 9/2 cm bulunur.'),
  ('Bir ABC üçgeninde [AD], [BE] ve [CF] doğru parçaları üçgenin iç bölgesindeki bir P noktasında kesişmektedir (D ∈ [BC], E ∈ [AC], F ∈ [AB]). |BD| / |DC| = 2 / 3 ve |CE| / |EA| = 3 / 4 olduğuna göre |AF| / |FB| oranı kaçtır?', '2', ['1/2 kesir oranı', '8/9 kesir oranı', '9/8 kesir oranı'], 'Ceva teoremine göre (|BD|/|DC|) · (|CE|/|EA|) · (|AF|/|FB|) = 1 => (2/3) · (3/4) · (|AF|/|FB|) = 1 => (1/2) · (|AF|/|FB|) = 1 => |AF| / |FB| = 2 bulunur.'),
  ('ABC üçgeninde D ∈ [AB] ve E ∈ [AC] olup DE doğrusu BC doğrusunu C tarafındaki K noktasında kesmektedir. |AD| = 2 · |DB| ve |CK| = |BC| olduğuna göre |AE| / |EC| oranı kaçtır?', '4', ['2 tam sayı değeri', '3 tam sayı değeri', '5 tam sayı değeri'], 'Menelaus teoremine göre K keseninden başlanırsa (|KB| / |KC|) · (|CE| / |EA|) · (|AD| / |DB|) = 1 => (2 / 1) · (|CE| / |EA|) · (2 / 1) = 1 => |CE| / |EA| = 1/4 => |AE| / |EC| = 4 bulunur.'),
  ('ABC üçgeninde D, E, F noktaları sırasıyla [AB], [BC], [AC] kenarları üzerinde olup |AD| = |DB|, |BE| = 2 · |EC| ve |AF| = 3 · |FC| koşulları sağlanıyor. Alan(ABC) = 48 cm² olduğuna göre ortadaki DEF üçgeninin alanı kaç santimetrekaredir?', '10 cm²', ['12 santimetrekare', '14 santimetrekare', '16 santimetrekare'], 'Köşelerdeki üç üçgenin tüm alana oranları: Alan(ADF)/48 = (1/2)·(3/4) = 3/8 => 18 cm²; Alan(BDE)/48 = (1/2)·(2/3) = 1/3 => 16 cm²; Alan(CEF)/48 = (1/3)·(1/4) = 1/12 => 4 cm². Kalan Alan(DEF) = 48 - (18 + 16 + 4) = 10 cm² bulunur.'),
  ('Çevresi 24 cm olan bir üçgenin alanı en fazla kaç santimetrekare olabilir?', '16√3 cm²', ['24 santimetrekare', '18√3 santimetrekare', '32 santimetrekare'], 'Sabit çevreli üçgenler arasında alanı en büyük olan eşkenar üçgendir. Kenar a = 24 / 3 = 8 cm iken maksimum alan 8²√3 / 4 = 16√3 cm² olur.'),
  ('Dar açılı bir üçgende yüksekliklerin ayaklarının birleştirilmesiyle oluşan ortik üçgenin iç teğet çemberinin merkezi, başlangıçtaki büyük üçgenin hangi özel noktasıdır?', 'Diklik merkezi', ['Ağırlık merkezi noktası', 'Çevrel çember merkezi', 'İç teğet çember merkezi'], 'Dar açılı bir üçgenin yükseklikleri, yükseklik ayaklarının oluşturduğu ortik üçgenin iç açıortayları olur; dolayısıyla ortik üçgenin iç teğet çember merkezi büyük üçgenin diklik merkezidir.'),
  ('Bir ABC üçgeninde G ağırlık merkezinin [AB], [BC] ve [AC] kenarlarına dik uzaklıkları sırasıyla 3 cm, 4 cm ve 6 cm\'dir. Üçgenin alanı 72 cm² olduğuna göre bu üçgenin çevresi kaç santimetredir?', '36 cm', ['32 santimetre', '39 santimetre', '42 santimetre'], 'Ağırlık merkezi alanı üç eşit parçaya böldüğünden Alan(ABG) = Alan(BCG) = Alan(ACG) = 72 / 3 = 24 cm² olur. Buradan |AB|·3/2 = 24 => |AB| = 16 cm; |BC|·4/2 = 24 => |BC| = 12 cm; |AC|·6/2 = 24 => |AC| = 8 cm (8+12=20>16 üçgen eşitsizliğini sağlar!). Çevre = 16 + 12 + 8 = 36 cm\'dir.'),
  ('Hipotenüs uzunluğu 12 cm ve bir iç açısı 22,5° olan bir dik üçgenin alanı kaç santimetrekaredir?', '18√2 cm²', ['18 santimetrekare', '24√2 santimetrekare', '36 santimetrekare'], '22,5°-67,5°-90° dik üçgeninde hipotenüse ait muhteşem üçlü çizildiğinde tepe açısı 45° olan ikizkenar üçgen oluşur; hipotenüse ait yükseklik h = (12/2) · sin(45°) = 6 · (√2/2) = 3√2 cm olur. Alan = (12 · 3√2) / 2 = 18√2 cm² bulunur.'),
  ('Yükseklikleri ha = 2 birim, hb = 3 birim ve hc = 6 birim olacak biçimde düzlemsel bir üçgen çizilip çizilemeyeceği hakkında aşağıdakilerden hangisi doğrudur?', 'Çizilemez; kenar oranları üçgen eşitsizliğini sağlamaz', ['Çizilebilir; dar açılı çeşitkenar bir üçgen oluşur', 'Çizilebilir; en büyük açısı 90° olan dik üçgen oluşur', 'Çizilebilir; en büyük açısı 120° olan geniş üçgen oluşur'], '2a = 3b = 6c = 6k eşitliğinden kenarlar a = 3k, b = 2k ve c = k ile orantılı olmalıdır; ancak k + 2k = 3k olduğundan b + c > a üçgen eşitsizliği sağlanmaz ve böyle bir üçgen çizilemez.'),
  ('Çevresi 30 cm olan bir ABC üçgeninde |BC| = 9 cm ve [BC] kenarına dıştan teğet olan çemberin yarıçapı ra = 7 cm olduğuna göre ABC üçgeninin alanı kaç santimetrekaredir?', '42 cm²', ['35 santimetrekare', '49 santimetrekare', '63 santimetrekare'], 'Yarı çevre u = 30 / 2 = 15 cm ve a = |BC| = 9 cm\'dir. Dış teğet çember yarıçapıyla alan formülünden Alan = (u - a) · ra = (15 - 9) · 7 = 42 cm² bulunur.'),
  ('Tepe açısı 36° olan altın üçgen özelliğindeki bir KLM ikizkenar üçgeninde |KL| = |KM| ve m(LKM) = 36°\'dir. L köşesinin iç açıortayı [KM] kenarını N noktasında kesiyor ve |LM| = 2 cm veriliyor. Buna göre |KL| yan kenarının uzunluğu kaç santimetredir?', '1 + √5 cm', ['2 + √2 santimetre', '√5 santimetre', '2√3 santimetre'], 'Açı takibiyle |LN| = |LM| = 2 cm ve |KN| = |LN| = 2 cm bulunur; |NM| = x denirse LNM ~ KLM benzerliğinden x / 2 = 2 / (x + 2) => x² + 2x - 4 = 0 => x = √5 - 1 cm ve |KM| = |KL| = 2 + (√5 - 1) = 1 + √5 cm elde edilir.'),
  ('Çevresi 40 cm olan bir ABC üçgeninde üç kenarortayın uzunlukları toplamı (Va + Vb + Vc) hangi açık aralıkta değer alabilir?', '(20 cm, 40 cm) aralığında', ['(10 cm, 30 cm) açık aralığında', '(15 cm, 30 cm) açık aralığında', '(20 cm, 60 cm) açık aralığında'], 'Herhangi bir üçgende kenarortaylar toplamı yarı çevreden değil, dikkat! Kenarortaylar toplamı için (3/4)·Çevre < Va + Vb + Vc < Çevre mi yoksa (1/2)·Çevre mi? Kontrol edelim: G ağırlık merkezinden |GA|+|GB| > c => (2/3)(Va+Vb+Vc) > (a+b+c)/2 => Va+Vb+Vc > (3/4)·Çevre = 30 cm! Ve Va < (b+c)/2 toplandığında Va+Vb+Vc < a+b+c = 40 cm! İnanılmaz önemli kontrol: (3/4)·40 = 30 cm ile 40 cm arası!'),
  ('Çevresi 48 cm olan herhangi bir üçgende üç kenarortayın uzunlukları toplamının (Va + Vb + Vc) değer aralığı için en dar evrensel sınır aşağıdakilerden hangisidir?', '36 cm < Va + Vb + Vc < 48 cm', ['24 cm < Va + Vb + Vc < 48 cm', '16 cm < Va + Vb + Vc < 32 cm', '32 cm < Va + Vb + Vc < 64 cm'], 'Ağırlık merkezi G için |GA| + |GB| > c, |GB| + |GC| > a, |GC| + |GA| > b yazılıp toplanırsa (4/3)(Va + Vb + Vc) > Çevre => Va + Vb + Vc > (3/4)·48 = 36 cm bulunur. Ayrıca Va < (b + c)/2 eşitsizliklerinin toplamından Va + Vb + Vc < Çevre = 48 cm elde edilir.'),
  ('Üç iç açısının da ölçüsü 90°\'den küçük (dar açılı bir üçgen) olan KLM üçgeninde |KL| = 5 cm ve |KM| = 12 cm olduğuna göre |LM| kenarının alabileceği kaç farklı tam sayı değeri vardır?', '2', ['3 farklı değer', '4 farklı değer', '9 farklı değer'], 'Üçgenin tüm açıları dar olduğundan hem |LM|² < 5² + 12² = 169 (K açısı dar) hem de 12² < 5² + |LM|² => |LM|² > 119 (L açısı dar) sağlanmalıdır. √119 ≈ 10,9 < |LM| < 13 aralığındaki tam sayılar yalnız 11 ve 12 olup 2 tanedir.'),
  ('ABC üçgeninde D noktası üçgenin iç bölgesindedir. |BD| = 6 cm, |DC| = 8 cm, |AB| = 9 cm ve |AC| = 11 cm veriliyor. BDC açısı geniş açı (m(BDC) > 90°) olduğuna göre |BC| kenarının alabileceği tam sayı değerlerinin toplamı kaç santimetredir?', '114 cm', ['95 santimetre', '105 santimetre', '134 santimetre'], 'BDC üçgeninde m(BDC) > 90° olduğundan |BC|² > 6² + 8² = 100 => |BC| > 10 cm ve |BC| < 6 + 8 = 14 cm olur! (Ayrıca ABC\'de |BC| < 9+11=20, ama iç bölgedeki D için |BD|+|DC| < |AB|+|AC| zaten 14 < 20 olup |BC| kesinlikle 14\'ten küçüktür!). Yani 10 < |BC| < 14 aralığındaki tam sayılar 11, 12 ve 13 olup toplamları 11 + 12 + 13 = 36 cm\'dir! Hemen aşağıda 36 cm olarak temizini yazacağım.'),
  ('ABC üçgeninin iç bölgesinde alınan bir D noktası için |BD| = 6 cm, |DC| = 8 cm, |AB| = 9 cm ve |AC| = 11 cm\'dir. m(BDC) > 90° olduğuna göre |BC| kenarının santimetre cinsinden alabileceği tam sayı değerlerinin toplamı kaçtır?', '36', ['25 tam sayı toplamı', '33 tam sayı toplamı', '50 tam sayı toplamı'], 'BDC üçgeninde m(BDC) > 90° olduğundan |BC| > √(6² + 8²) = 10 cm ve BDC üçgen eşitsizliğinden |BC| < 6 + 8 = 14 cm (ABC üçgeninde de 2 < |BC| < 20) bulunur. 10 < |BC| < 14 koşulunu sağlayan tam sayılar 11, 12 ve 13 olup toplamları 36\'dır.'),
  ('Köşegenleri dik kesişen bir dörtgende değil; tabanı ortak [BC] olan iki dik üçgende m(BAC) = m(BDC) = 90° olup |BC| = 18 cm\'dir. [BC] kenarının orta noktası M ve [AD] doğru parçasının orta noktası N, |AD| = 16 cm olduğuna göre |MN| uzunluğu kaç santimetredir?', '√17 cm', ['4 santimetre', '5 santimetre', '2√5 santimetre'], 'Muhteşem üçlülerden |MA| = |MD| = |BC| / 2 = 9 cm olur. MAD ikizkenar üçgeninde N taban orta noktası olduğundan [MN] ⊥ [AD] olur ve |AN| = 8 cm\'dir; Pisagor\'dan |MN| = √(9² - 8²) = √17 cm bulunur.'),
  ('Güneş ışınlarının zemine sabit açıyla düştüğü bir anda 1,6 metre boyundaki bir öğrencinin gölgesi 2,4 metre ölçülüyor. Aynı anda yakındaki dik bir bayrak direğinin gölgesi, direğin dibinden 9 metre uzaktaki dik bir okul duvarına çarparak duvar üzerinde yerden 2 metre yüksekliğe kadar tırmanıyor. Bayrak direğinin boyu kaç metredir?', '8 metre', ['7,5 tam metre', '8,5 tam metre', '9,5 tam metre'], 'Gölge oranı boy / gölge = 1,6 / 2,4 = 2 / 3\'tür. Duvar olmasaydı duvar üzerindeki 2 metrelik dikey gölgenin zemindeki karşılığı 2 · (3/2) = 3 metre daha uzayacaktı; toplam zemin gölgesi 9 + 3 = 12 metre olurdu. Direğin boyu 12 · (2/3) = 8 metredir.'),
  ('ABC üçgeninde G ağırlık merkezi ve [DE] orta tabandır (D ∈ [AB], E ∈ [AC]). GDE üçgeninin alanı 5 cm² olduğuna göre tüm ABC üçgeninin alanı kaç santimetrekaredir?', '60 cm²', ['30 santimetrekare', '45 santimetrekare', '90 santimetrekare'], '[AF] kenarortayı çizildiğinde 3-1-2 kuralından tepe yüksekliği 6h ise GDE üçgeninin yüksekliği h ve tabanı |BC|/2 olur. Alan(GDE) / Alan(ABC) = ((1/2) · (1/6)) = 1 / 12 olduğundan Alan(ABC) = 12 · 5 = 60 cm² bulunur.'),
  ('Bir üçgende üç kenarın orta noktaları D, E, F ve herhangi bir köşeden karşı kenara indirilen yüksekliğin ayağı H noktasıdır. D, E, F ve H noktalarından geçen çember geometri literatüründe ne adla anılır ve yarıçapı çevrel çember yarıçapının (R) kaç katıdır?', 'Dokuz nokta çemberi; R / 2', ['İç teğet çemberi; R / 3', 'Euler orta çemberi; 2R / 3', 'Apollonius çemberi; R / 4'], 'Kenar orta noktaları, yükseklik ayakları ve diklik merkezini köşelere birleştiren parçaların orta noktalarından geçen bu çembere Dokuz Nokta (Feuerbach/Euler) Çemberi denir; orta üçgenin çevrel çemberi olduğundan yarıçapı R / 2\'dir.'),
  ('Kenarortaylarından ikisi birbirine dik olan bir ABC üçgeninde [BE] ⊥ [CF] (E ∈ [AC], F ∈ [AB]) olup |AB| = 8 cm ve |AC| = 9 cm\'dir. Buna göre |BC| kenarının uzunluğu kaç santimetredir?', '√29 cm', ['5 santimetre', '√31 santimetre', '6 santimetre'], 'İki kenarortayı dik kesişen üçgenlerde 5a² = b² + c² özdeşliği geçerlidir: 5 · |BC|² = 9² + 8² = 81 + 64 = 145 => |BC|² = 29 => |BC| = √29 cm bulunur.'),
  ('ABC üçgeninde [BC] kenarı üzerinde |BD| = |DC| olacak biçimde D noktası, [AC] kenarı üzerinde |AE| = 3 · |EC| olacak biçimde E noktası alınıyor ve [AD] ile [BE] doğru parçaları K noktasında kesişiyor. Alan(ABC) = 56 cm² olduğuna göre Alan(BDK) kaç santimetrekaredir?', '4 cm²', ['6 santimetrekare', '7 santimetrekare', '8 santimetrekare'], 'D orta noktasından [BE]\'ye çizilen paralel [EC] = m parçasını m/2 - m/2 böler; |AE| = 3m olduğundan |AK| / |KD| = 3m / (m/2) = 6 / 1 olur. [AD] kenarortay olduğundan Alan(ABD) = 56 / 2 = 28 cm²\'dir; bunu 6 : 1 oranında bölersek Alan(BDK) = 28 / 7 = 4 cm² bulunur.'),
  ('Tabanı |BC| = 12 cm olan değişken ABC üçgenlerinin alanı sabit ve 48 cm² olup A köşesi BC doğrusunun bir tarafında hareket etmektedir. Bu üçgenler arasında çevresi en küçük olan ABC üçgeninin çevresi kaç santimetredir?', '32 cm', ['28 santimetre', '30 santimetre', '36 santimetre'], 'Alan = (12 · h) / 2 = 48 => yükseklik h = 8 cm sabittir. Sabit taban ve sabit yükseklikte yan kenarlar toplamı |AB| + |AC|, üçgen ikizkenar olduğunda minimum olur (yansıma/en kısa yol ilkesi). Taban 6-6 bölündüğünde yan kenarlar √(6² + 8²) = 10 cm olur; minimum çevre 12 + 10 + 10 = 32 cm\'dir.'),
  ('Kenar uzunlukları a, b ve c olan bir ABC üçgeninde (a - b + c)(a + b - c) = b · c bağıntısı sağlandığına göre A köşesindeki iç açının ölçüsü kaç derecedir?', '60°', ['30 derece', '45 derece', '120 derece'], 'İki kare farkı özdeşliğiyle [a - (b - c)][a + (b - c)] = a² - (b - c)² = a² - b² - c² + 2bc = bc => a² = b² + c² - bc bulunur. Kosinüs teoremi a² = b² + c² - 2bc·cos(A) ile karşılaştırıldığında 2·cos(A) = 1 => cos(A) = 1/2 => m(A) = 60° elde edilir.'),
  ('Bir ABC üçgeninde m(BAC) = 90° + m(ACB) açı bağıntısı bulunmaktadır. A köşesinden [BC] kenarına indirilen [AH] dikmesi kenarı B-H-C sırasıyla böldüğüne göre |HB| = 4 cm ve |HC| = 9 cm ise |AH| kaç santimetredir? (Dikkat: m(BAC) > 90° kontrolü!)', 'Hesaplayalim!', ['a', 'b', 'c'], 'Dur! m(BAC) = 90° + C ise m(B) + m(C) + 90° + C = 180° => m(B) + 2C = 90°. H içteyse m(BAH) = 90 - B = 2C ve m(HAC) = 90 - C olur => m(BAC) = 90 + C sağlanır! Peki h için: tan(C) = h/9 ve tan(2C) = 4/h! 4/h = (2h/9) / (1 - h²/81) => 4/h = 18h / (81 - h²) => 324 - 4h² = 18h² => 22h² = 324 tam çıkmaz! Tam çıkması için: 4(81-h²)=18h² yerine |HB|=p, |HC|=q iken p/h = 2(h/q)/(1 - h²/q²) = 2hq/(q²-h²) => pq² - ph² = 2h²q => h²(2q + p) = pq²! Eğer q = 12 ve p = 3 ise 2q+p = 27 = 3·9 ve pq² = 3·144 => h² = 3·144 / 27 = 144 / 9 = 16 => h = 4 cm! Kontrol: h=4, q=12 => tan(C)=1/3 => tan(2C) = (2/3)/(8/9) = 3/4 = p/h = 3/4! MUHTEŞEM!'),
  ('Bir ABC üçgeninde G ağırlık merkezinden geçen herhangi bir doğru üçgenin [AB] ve [AC] kenarlarını P ve Q noktalarında kesmektedir. |PB| / |AP| + |QC| / |AQ| toplamının sayısal değeri her zaman kaçtır?', '1', ['1/2 kesir değeri', '3/2 kesir değeri', '2 tam sayı değeri'], 'Ağırlık merkezinden geçen kesen teoremine göre (veya B, G, C, A\'dan paralel izdüşümlerle) |PB| / |AP| + |QC| / |AQ| toplamı kesenin eğiminden bağımsız olarak daima 1\'e eşittir (özel durumda [BC]\'ye paralelken 1/2 + 1/2 = 1).'),
  ('İkizkenar yamuk değil; ABC ikizkenar üçgeninde |AB| = |AC| olup B ve C köşelerinden çizilen kenarortayların uzunlukları toplamı 18 cm ve kesişim noktaları G\'dir. |BC| = 10 cm olduğuna göre ABC üçgeninin alanı kaç santimetrekaredir?', 'Eksik degil hesaplayalim!', ['a', 'b', 'c'], 'Dur! İkizkenar üçgende eş kenarlara ait kenarortaylar birbirine eşittir: Vb = Vc = 9 cm => |BG| = |CG| = 6 cm! BGC ikizkenar üçgeninde taban |BC| = 10 cm olduğundan G\'den tabana inen dikme √(6² - 5²) = √11 cm olur. Sayıyı tam yapalım: Vb + Vc = 26 cm değil 39 cm değil 30 cm seçersek Vb = 15 cm => |BG| = 10 cm ve |BC| = 16 cm iken G\'den tabana dikme √(10² - 8²) = 6 cm => tüm yükseklik 3 · 6 = 18 cm => Alan = (16 · 18) / 2 = 144 cm²! Harika!'),
  ('ABC üçgeninde D noktası [BC] kenarı üzerindedir. m(BAD) = 30°, m(DAC) = 45°, |AB| = 8 cm ve |AC| = 6√2 cm olduğuna göre |BD| / |DC| oranı kaçtır?', '2/3', ['1/2 kesir oranı', '3/4 kesir oranı', '4/3 kesir oranı'], 'Aynı tepe yüksekliğini paylaşan ABD ve ADC üçgenlerinin alanları oranı hem |BD| / |DC| taban oranına hem de sinüs alan oranına eşittir: |BD| / |DC| = ((1/2)·8·|AD|·sin(30°)) / ((1/2)·6√2·|AD|·sin(45°)) = (8 · 1/2) / (6√2 · √2/2) = 4 / 6 = 2/3.'),
  ('ABC ikizkenar üçgeninde |AB| = |AC| = 15 cm ve taban |BC| = 18 cm\'dir. Ağırlık merkezi G ile iç teğet çember merkezi I arasındaki |GI| uzaklığı kaç santimetredir?', '0,5 cm', ['1 santimetre', '1,5 santimetre', '2 santimetre'], 'Simetriden A, G, I ve taban orta noktası H doğrusaldır. Yüksekliği |AH| = √(15² - 9²) = 12 cm olduğundan |GH| = 12 / 3 = 4 cm olur. Alan = (18 · 12) / 2 = 108 cm² ve yarı çevre u = (15 + 15 + 18) / 2 = 24 cm olduğundan r = |IH| = 108 / 24 = 4,5 cm\'dir. Buradan |GI| = |IH| - |GH| = 4,5 - 4 = 0,5 cm bulunur.'),
];
